import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.BZzouRtU.js";const i="/study/images/compilers/libraries-apis-and-sdks.svg",f=JSON.parse('{"title":"ライブラリ・API・SDK — 用意された機能を使う","description":"","frontmatter":{"title":"ライブラリ・API・SDK — 用意された機能を使う","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"compilers","summary":"ゲームからウィンドウや画像の機能を呼ぶ場面で、ライブラリ、API、SDK、ヘッダー、パッケージ、依存関係の意味を説明する。","aliases":["ライブラリ","library","API","SDK","ヘッダー","header","パッケージ","package","依存関係","dependency","静的ライブラリ","DLL","動的ライブラリ"],"verification":"MicrosoftのWindows SDK・Win32 API・C++ライブラリ・NuGetの資料に照合（2026-11-07）"}},"headers":[],"relativePath":"compilers/libraries-apis-and-sdks.md","filePath":"compilers/libraries-apis-and-sdks.md"}'),o={name:"compilers/libraries-apis-and-sdks.md"};function n(l,e,d,c,p,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="ライブラリ・api・sdk-—-用意された機能を使う" tabindex="-1">ライブラリ・API・SDK — 用意された機能を使う <a class="header-anchor" href="#ライブラリ・api・sdk-—-用意された機能を使う" aria-label="Permalink to &quot;ライブラリ・API・SDK — 用意された機能を使う&quot;">​</a></h1><p>ゲームを作るときは、ウィンドウを開いたり画像ファイルを読んだりする処理に、既存の機能を使えます。機能を呼び出すための約束がAPI、その処理を実装した部品がライブラリ、開発に使う一式がSDKです。<a href="https://learn.microsoft.com/en-us/windows/apps/windows-sdk/" target="_blank" rel="noreferrer">MicrosoftのWindows SDK</a></p><h2 id="まず三つの役割を区別する" tabindex="-1">まず三つの役割を区別する <a class="header-anchor" href="#まず三つの役割を区別する" aria-label="Permalink to &quot;まず三つの役割を区別する&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>意味</th><th>例</th></tr></thead><tbody><tr><td><strong>ライブラリ</strong></td><td>他のプログラムから使えるようにまとめたコードや機能。</td><td>数学の計算、画像の読み込み、音声の再生を担当する部品。</td></tr><tr><td><strong>API</strong>（Application Programming Interface）</td><td>機能を利用する側との接点。呼び出し方や、渡す値・返る値などの規則を含む。</td><td>ウィンドウを作る関数の名前、引数、結果、失敗時の規則。</td></tr><tr><td><strong>SDK</strong>（Software Development Kit）</td><td>特定の環境や製品向けに開発するための一式。</td><td>ヘッダー、ライブラリ、開発ツールなどをまとめたWindows SDK。</td></tr></tbody></table><p>APIの説明を読むと、「この関数へどんな値を渡すか」「成功と失敗を何で判断するか」「返った資源をいつ解放するか」を調べられます。例えばWindowsの<code>CreateWindowExW</code>は、ウィンドウ名や寸法などを受け取り、成功時はウィンドウを操作するためのハンドルを、失敗時は<code>NULL</code>を返します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-createwindowexw" target="_blank" rel="noreferrer">CreateWindowExWの引数と戻り値</a></p><h2 id="画像を読み込む依頼で考える" tabindex="-1">画像を読み込む依頼で考える <a class="header-anchor" href="#画像を読み込む依頼で考える" aria-label="Permalink to &quot;画像を読み込む依頼で考える&quot;">​</a></h2><p>次の図では、説明用の架空のAPI <code>load_image</code> を使います。ゲームは画像のパスを渡し、ライブラリがファイルの内容を読んで画像として解釈し、結果を返すものとします。利用側はAPIの規則に従い、受け取った画像を使ったり、失敗を処理したりします。</p><figure class="study-figure"><img src="'+i+`" alt="ゲームがAPIの規則に従って画像のパスを渡し、ライブラリの実装が画像を読む。画像または失敗の情報が呼び出し元へ返る。SDKには開発に使うヘッダー、ライブラリ、ツールなどが含まれる。" width="760" height="430" loading="lazy"><figcaption>上は呼び出しと結果、下は開発に使う一式の例です。SDKの内容は製品によって異なります。<a href="/study/images/compilers/libraries-apis-and-sdks.svg" target="_blank" rel="noopener noreferrer">APIとSDKの図を拡大</a></figcaption></figure><p>APIという言葉は、同じプロセス内の関数呼び出し以外にも使われます。例えばサーバーがHTTPで受け付けるAPIでは、URLや要求の形式、応答の意味が接点になります。利用側は、その接点を通じて相手の機能を使います。<a href="https://learn.microsoft.com/en-us/azure/architecture/best-practices/api-design" target="_blank" rel="noreferrer">MicrosoftのWeb APIの設計</a> · <a href="/study/network/http-messages.html">HTTP通信</a></p><h2 id="c-のヘッダーと実装" tabindex="-1">C++のヘッダーと実装 <a class="header-anchor" href="#c-のヘッダーと実装" aria-label="Permalink to &quot;C++のヘッダーと実装&quot;">​</a></h2><p>C++では、別のファイルにある関数を使うために、その関数の名前、引数、返す型などの<strong>宣言</strong>を読めるようにします。宣言をまとめるファイルが<strong>ヘッダー</strong>で、<code>#include</code>で取り込む形がよく使われます。関数の中身である<strong>定義</strong>は、別のソースファイルやライブラリに置くことができます。<a href="https://learn.microsoft.com/en-us/cpp/cpp/header-files-cpp?view=msvc-170" target="_blank" rel="noreferrer">Microsoftのヘッダーファイル</a></p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 説明用の宣言。関数の中身は別に用意する。</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> add_score</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> current</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> bonus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>コンパイラーがこの宣言を読むと、呼び出しの名前や型を確かめられます。後でリンクする際には、使う関数の実装もそろえる必要があります。ヘッダー内に定義を置く形のライブラリもあるため、配布される部品を確認してビルドへ加えます。<a href="https://learn.microsoft.com/en-us/cpp/cpp/header-files-cpp?view=msvc-170" target="_blank" rel="noreferrer">Microsoftのヘッダーと定義</a> · <a href="/study/compilers/source-code-and-execution.html">ソースコードから実行まで</a></p><h2 id="静的ライブラリと動的ライブラリ" tabindex="-1">静的ライブラリと動的ライブラリ <a class="header-anchor" href="#静的ライブラリと動的ライブラリ" aria-label="Permalink to &quot;静的ライブラリと動的ライブラリ&quot;">​</a></h2><p><strong>静的ライブラリ</strong>は、リンク時に使うコードをまとめたものです。必要なオブジェクトコードを取り出し、実行ファイルなどへ組み込む構成で使います。WindowsのC++では<code>.lib</code>という拡張子が一例です。<a href="https://learn.microsoft.com/en-us/cpp/build/walkthrough-creating-and-using-a-static-library-cpp?view=msvc-170" target="_blank" rel="noreferrer">Microsoftの静的ライブラリ</a></p><p><strong>動的ライブラリ・共有ライブラリ</strong>は、実行時にプロセスへ読み込んで使う形のライブラリです。WindowsのネイティブDLLを使う構成では、ビルド時に参照する<strong>インポートライブラリ</strong>も<code>.lib</code>になる場合があります。同じ拡張子のファイルでも、含まれる情報と使い方を確認します。<a href="https://learn.microsoft.com/en-us/cpp/build/linking-an-executable-to-a-dll?view=msvc-170" target="_blank" rel="noreferrer">MicrosoftのDLLとリンク</a> · <a href="/study/runtime/cpp-internals/object-files-and-libraries.html">オブジェクトファイル・DLLの詳細</a></p><h2 id="パッケージと依存関係" tabindex="-1">パッケージと依存関係 <a class="header-anchor" href="#パッケージと依存関係" aria-label="Permalink to &quot;パッケージと依存関係&quot;">​</a></h2><p><strong>パッケージ</strong>は、コードや関連するファイルを配布するためにまとめた単位です。例えば.NETのNuGetパッケージには、ライブラリのDLL、バージョンなどを記録した情報、関連ファイルを含められます。<strong>パッケージマネージャー</strong>は、取得やプロジェクトへの追加などを支援する道具です。<a href="https://learn.microsoft.com/en-us/nuget/what-is-nuget" target="_blank" rel="noreferrer">MicrosoftのNuGetの役割</a></p><p>アプリAがライブラリBを必要とするとき、AはBに<strong>依存する</strong>といいます。Bが別のライブラリCを必要とすれば、Aを動かすためにCも必要になる場合があります。パッケージにはこうした依存先を記録でき、復元時に必要なバージョンをそろえます。<a href="https://learn.microsoft.com/en-us/nuget/concepts/dependency-resolution" target="_blank" rel="noreferrer">Microsoftのパッケージの依存関係</a></p><h2 id="機能を追加するときに確認するもの" tabindex="-1">機能を追加するときに確認するもの <a class="header-anchor" href="#機能を追加するときに確認するもの" aria-label="Permalink to &quot;機能を追加するときに確認するもの&quot;">​</a></h2><ol><li>使いたい機能のAPIを読み、入力、結果、失敗、資源の解放の規則を確認する。</li><li>対象OS・CPU・言語に合うSDKやパッケージを用意する。</li><li>ヘッダー、ライブラリ、必要な実行時ファイルを、指定された方法でプロジェクトへ追加する。</li><li>ビルドと実行を確かめ、APIの結果を使って処理を続ける。</li></ol><p>具体的な設定は、利用するライブラリの配布方法とビルドツールによって変わります。API名、配布物の版、対象環境を合わせて調べると、どの部品を用意するか追えます。<a href="https://learn.microsoft.com/en-us/windows/apps/windows-sdk/" target="_blank" rel="noreferrer">Windows SDKの構成</a> · <a href="/study/tools/build/build-tools-cmake.html">ビルドツール</a> · <a href="/study/tools/development-tools-basics.html">開発ツールの基本</a></p>`,22)])])}const u=t(o,[["render",n]]);export{f as __pageData,u as default};
